solution:
// A vector clock is a plain object { nodeId: counter }. A missing node means 0.

function tick(clock, nodeId) {
  return { ...clock, [nodeId]: (clock[nodeId] || 0) + 1 };
}

function merge(a, b) {
  const out = { ...a };
  for (const [node, n] of Object.entries(b)) out[node] = Math.max(out[node] || 0, n);
  return out;
}

function compare(a, b) {
  let aBigger = false, bBigger = false;
  const nodes = new Set([...Object.keys(a), ...Object.keys(b)]);
  for (const node of nodes) {
    const x = a[node] || 0, y = b[node] || 0;
    if (x > y) aBigger = true;
    if (y > x) bBigger = true;
  }
  if (aBigger && bBigger) return 'concurrent';
  if (aBigger) return 'after';
  if (bBigger) return 'before';
  return 'equal';
}

class Replica {
  constructor(id) {
    this.id = id;
    this.versions = []; // [{ value, clock }]; more than one = conflicting siblings
  }

  // A local write has seen every version this replica holds, so it supersedes all of them.
  write(value) {
    let seen = {};
    for (const v of this.versions) seen = merge(seen, v.clock);
    const version = { value, clock: tick(seen, this.id) };
    this.versions = [version];
    return { value: version.value, clock: { ...version.clock } };
  }

  // A version arriving from another replica (possibly late, duplicated or out of order).
  receive(incoming) {
    for (const v of this.versions) {
      const c = compare(incoming.clock, v.clock);
      if (c === 'before' || c === 'equal') return false; // stale or duplicate
    }
    this.versions = this.versions.filter((v) => compare(v.clock, incoming.clock) !== 'before');
    this.versions.push({ value: incoming.value, clock: { ...incoming.clock } });
    return true;
  }

  read() {
    return this.versions.map((v) => v.value);
  }
}

tests.code:
const c = { VA: 1 };
const t = tick(c, 'VA');
assertEqual(t, { VA: 2 });
assertEqual(c, { VA: 1 }, 'tick must not mutate');
const a = { VA: 2, OR: 1 }, b = { OR: 3, EU: 1 };
assertEqual(merge(a, b), { VA: 2, OR: 3, EU: 1 });
assertEqual(a, { VA: 2, OR: 1 }, 'merge must not mutate');

assertEqual(compare({ VA: 1 }, { VA: 2, OR: 1 }), 'before');
assertEqual(compare({ VA: 2, OR: 1 }, { VA: 1 }), 'after');
assertEqual(compare({ VA: 1, OR: 0 }, { VA: 1 }), 'equal');
assertEqual(compare({}, {}), 'equal');

const va = new Replica('VA'), or = new Replica('OR');
const v1 = va.write('Alice');
or.receive(v1);
const v2 = or.write('Alice (paid)');
assertEqual(v2.clock, { VA: 1, OR: 1 });
assertEqual(va.receive(v2), true);
assertEqual(va.read(), ['Alice (paid)']);
assertEqual(va.receive(v1), false, 'v1 arrives late (retry): stale, must be ignored');
assertEqual(va.read(), ['Alice (paid)']);

const va = new Replica('VA'), or = new Replica('OR');
const v = va.write('Alice');
assertEqual(or.receive(v), true);
assertEqual(or.receive(v), false);
assertEqual(or.read(), ['Alice']);

const va = new Replica('VA'), or = new Replica('OR');
const a = va.write('Alice');
const b = or.write('Bob');
va.receive(b); or.receive(a);
assertEqual(va.read().slice().sort(), ['Alice', 'Bob']);
assertEqual(or.read().slice().sort(), ['Alice', 'Bob']);

const va = new Replica('VA'), or = new Replica('OR');
const a = va.write('Alice');
const b = or.write('Bob');
va.receive(b); or.receive(a);
const fix = va.write('Alice (Bob refunded)');
assertEqual(fix.clock, { VA: 2, OR: 1 });
assertEqual(or.receive(fix), true);
assertEqual(or.read(), ['Alice (Bob refunded)']);
assertEqual(va.read(), ['Alice (Bob refunded)']);
